Write a C program utilizing appropriate decision-making statements to compute the commission based on the input sales amount, considering the following conditions:

a. For sales amounts less than or equal to Rs. 5000 no commission is given to females, males receive a commission of 2%.

b. For sales amounts greater than Rs. 5000 and up to Rs. 10,000 females receive a commission of 2%, males receive a commission of 4%.

c. For sales amounts exceeding Rs. 10,000, both males and females receive a commission of 6%.

**Sol:**
```c
#include <stdio.h>
int main() {
    float sales_amount, commission = 0;
    char gender;

    // Input sales amount and gender
    printf("Enter sales amount: Rs. ");
    scanf("%f", &sales_amount);
    printf("Enter gender (M/F): ");
    scanf(" %c", &gender);  // Note the space before %c to skip whitespace

    printf("\n=== Using Nested If Structure ===\n");

    // Calculate commission using nested if
    if (sales_amount > 10000) {
        commission = sales_amount * 0.06;
    } else {
        if (gender == 'F' || gender == 'f') {
            if (sales_amount <= 5000) {
                commission = 0;
            } else {
                commission = sales_amount * 0.02;
            }
        } else if (gender == 'M' || gender == 'm') {
            if (sales_amount <= 5000) {
                commission = sales_amount * 0.02;
            } else {
                commission = sales_amount * 0.04;
            }
        } else {
            printf("Invalid gender entered!\n");
            return 1;
        }
    }
    printf("Commission (Nested If): Rs. %.2f\n", commission);

    // Reset commission for else-if ladder calculation
    commission = 0;

    printf("\n=== Using Else-If Ladder Structure ===\n");

    // Calculate commission using else-if ladder
    if (sales_amount > 10000) {
        commission = sales_amount * 0.06;
    }
    else if ((gender == 'F' || gender == 'f') && sales_amount <= 5000) {
        commission = 0;
    }
    else if ((gender == 'F' || gender == 'f') && sales_amount > 5000) {
        commission = sales_amount * 0.02;
    }
    else if ((gender == 'M' || gender == 'm') && sales_amount <= 5000) {
        commission = sales_amount * 0.02;
    }
    else if ((gender == 'M' || gender == 'm') && sales_amount > 5000) {
        commission = sales_amount * 0.04;
    }
    else {
        printf("Invalid gender entered!\n");
        return 1;
    }
    printf("Commission (Else-If Ladder): Rs. %.2f\n", commission);
    return 0;
}
```

