Write a complete C program to read a number and check for the following operations using a while Loop.

- Display “EVEN” if all the digits in the number are even.
- Display “ODD” if all the digits in the number are odd.
- Display “neither EVEN nor ODD” if all the digits in the number are neither even nor odd.

**Sol:**
```c
#include <stdio.h>
int main() {
    int number, temp;
    int hasEven = 0, hasOdd = 0;

    // Input the number
    printf("Enter a number: ");
    scanf("%d", &number);

    // Store original number for printing later
    temp = number;

    // Handle negative numbers
    if (number < 0) {
        number = -number;
    }

    // Handle zero separately
    if (number == 0) {
        printf("%d contains all EVEN digits\n", temp);
        return 0;
    }

    // Check each digit using while loop
    while (number > 0) {
        int digit = number % 10;  // Get last digit

        // Check if digit is even or odd
        if (digit % 2 == 0) {
            hasEven = 1;
        } else {
            hasOdd = 1;
        }

        // Break early if we found both even and odd digits
        if (hasEven && hasOdd) {
            break;
        }

        number = number / 10;  // Remove last digit
    }

    // Print result based on what types of digits were found
    if (hasEven && !hasOdd) {
        printf("%d contains all EVEN digits\n", temp);
    }
    else if (!hasEven && hasOdd) {
        printf("%d contains all ODD digits\n", temp);
    }
    else {
        printf("%d is neither EVEN nor ODD (contains both even and odd digits)\n", temp);
    }

    return 0;
}
```

