int age[] = {16,25,32,48,52,65};
values[i] = 0;
```

**Program**
```c
#include <stdio.h>
int main() {
    int N;

    // Input array size
    printf("Enter the number of elements: ");
    scanf("%d", &N);

    // Declare arrays
    int arr[100];  // Original array
    int primes[100];  // Array for prime numbers
    int non_primes[100];  // Array for non-prime numbers
    int prime_count = 0, non_prime_count = 0;

    // Input array elements
    printf("Enter %d elements:\n", N);
    for (int i = 0; i < N; i++) {
        scanf("%d", &arr[i]);
    }

    // Split array into prime and non-prime
    for (int i = 0; i < N; i++) {
        int num = arr[i];
        int isPrime = 1; // 1 means prime, 0 means not prime

        // Check if number is prime
        if (num <= 1) {
            isPrime = 0;
        }
        else if (num == 2) {
            isPrime = 1;
        }
        else if (num % 2 == 0) {
            isPrime = 0;
        }
        else {
            for (int j = 3; j * j <= num; j += 2) {
                if (num % j == 0) {
                    isPrime = 0;
                    break;
                }
            }
        }

        // Add to appropriate array
        if (isPrime) {
            primes[prime_count] = num;
            prime_count++;
        } else {
            non_primes[non_prime_count] = num;
            non_prime_count++;
        }
    }

    // Print prime numbers array
    printf("\nPrime numbers: ");
    if (prime_count == 0) {
        printf("None");
    } else {
        for (int i = 0; i < prime_count; i++) {
            printf("%d ", primes[i]);
        }
    }

    // Print non-prime numbers array
    printf("\nNon-prime numbers: ");
    if (non_prime_count == 0) {
        printf("None");
    } else {
        for (int i = 0; i < non_prime_count; i++) {
            printf("%d ", non_primes[i]);
        }
    }
    printf("\n");
    return 0;
}
```

