Write a C program to read the elements of a 3 × 3 matrix and sort the elements of each row in ascending order. Display the matrix after sorting each row.

**Sol:**
```c
#include <stdio.h>
int main() {
    int a[3][3], i, j, k, temp;

    printf("Enter elements of 3x3 matrix:\n");
    for(i=0; i<3; i++)
        for(j=0; j<3; j++)
            scanf("%d", &a[i][j]);

    // Sorting each row in ascending order
    for(i=0; i<3; i++) {
        for(j=0; j<3-1; j++) {
            for(k=j+1; k<3; k++) {
                if(a[i][j] > a[i][k]) {
                    temp = a[i][j];
                    a[i][j] = a[i][k];
                    a[i][k] = temp;
                }
            }
        }
    }

    printf("\nMatrix after sorting each row in ascending order:\n");
    for(i=0; i<3; i++) {
        for(j=0; j<3; j++)
            printf("%d ", a[i][j]);
        printf("\n");
    }
    return 0;
}
```

