Design and implement a menu-driven C program using functions (without using structures) to manage student records. The program should allow the user to:

1. Add new student details (Name, Roll Number, Marks)
2. Display all student details
3. Search for a student by roll number
4. Calculate and display the class average marks

**Sol:**
```c
#include <stdio.h>
#include <string.h>

int main() {
    int rollNo[100];
    char name[100][50];
    float marks[100];
    int n = 0;  // Number of students
    int choice;

    void addStudent() {
        printf("Enter Roll Number: ");
        scanf("%d", &rollNo[n]);
        printf("Enter Name: ");
        scanf(" %[^
]", name[n]);
        printf("Enter Marks: ");
        scanf("%f", &marks[n]);
        n++;
        printf("Student added successfully.\n");
    }

    void displayAll() {
        if (n == 0) {
            printf("No student records available.\n");
            return;
        }
        printf("\nStudent Records:\n");
        for (int i = 0; i < n; i++) {
            printf("Roll Number: %d\n", rollNo[i]);
            printf("Name: %s\n", name[i]);
            printf("Marks: %.2f\n", marks[i]);
            printf("---------------------\n");
        }
    }

    void searchStudent() {
        if (n == 0) {
            printf("No student records to search.\n");
            return;
        }
        int roll, found = 0;
        printf("Enter Roll Number to search: ");
        scanf("%d", &roll);
        for (int i = 0; i < n; i++) {
            if (rollNo[i] == roll) {
                printf("\nRecord Found:\n");
                printf("Roll Number: %d\n", rollNo[i]);
                printf("Name: %s\n", name[i]);
                printf("Marks: %.2f\n", marks[i]);
                found = 1;
                break;
            }
        }
        if (!found)
            printf("Record not found.\n");
    }

    void classAverage() {
        if (n == 0) {
            printf("No records to calculate average.\n");
            return;
        }
        float sum = 0;
        for (int i = 0; i < n; i++)
            sum += marks[i];
        printf("Class Average Marks: %.2f\n", sum / n);
    }

    do {
        printf("\n== Student Record Menu ==\n");
        printf("1. Add Student\n");
        printf("2. Display All Students\n");
        printf("3. Search Student by Roll Number\n");
        printf("4. Calculate Class Average\n");
        printf("5. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1: addStudent(); break;
            case 2: displayAll(); break;
            case 3: searchStudent(); break;
            case 4: classAverage(); break;
            case 5: printf("Exiting...\n"); break;
            default: printf("Invalid choice. Please try again.\n");
        }
    } while (choice != 5);

    return 0;
}
```

