Write a C program using functions to calculate Simple Interest (SI), Compound Interest (CI), and their Difference. The program should take the principal, rate, and time as inputs and use separate functions for each calculation - one for SI, one for CI, and one for finding the difference.

**Hint:** SI = (P × R × T) / 100,
CI = P ((1 + R / 100)^T) - P

**Sol:**
```c
#include <stdio.h>
#include <math.h>

// Function to calculate Simple Interest
float calculateSI(float P, float R, float T) {
    return (P * R * T) / 100.0;
}

// Function to calculate Compound Interest
float calculateCI(float P, float R, float T) {
    float amount = P * pow((1 + R / 100.0), T);
    return amount - P;
}

// Function to calculate difference between CI and SI
float difference(float CI, float SI) {
    return CI - SI;
}

int main() {
    float P, R, T, si, ci, diff;

    // Input from the user
    printf("Enter Principal: ");
    scanf("%f", &P);

    printf("Enter Rate of Interest: ");
    scanf("%f", &R);

    printf("Enter Time (in years): ");
    scanf("%f", &T);

    // Function calls
    si = calculateSI(P, R, T);
    ci = calculateCI(P, R, T);
    diff = difference(ci, si);

    // Output
    printf("\nSimple Interest: %.2f", si);
    printf("\nCompound Interest: %.2f", ci);
    printf("\nDifference (CI - SI): %.2f\n", diff);

    return 0;
}
```

