Design a program using functions with pointer parameters to compute both row-wise and column-wise sums of a matrix.

**Sol:**
```c
#include <stdio.h>
void rowWiseSum(int *mat, int rows, int cols, int *rowSum) {
    for (int i = 0; i < rows; i++) {
        rowSum[i] = 0;
        for (int j = 0; j < cols; j++) {
            rowSum[i] += *(mat + i * cols + j);  // pointer arithmetic
        }
    }
}

void colWiseSum(int *mat, int rows, int cols, int *colSum) {
    for (int j = 0; j < cols; j++) {
        colSum[j] = 0;
        for (int i = 0; i < rows; i++) {
            colSum[j] += *(mat + i * cols + j);  // pointer arithmetic
        }
    }
}

int main() {
    int rows, cols;

    // Input for matrix size
    printf("Enter number of rows: ");
    scanf("%d", &rows);
    printf("Enter number of columns: ");
    scanf("%d", &cols);

    int mat[rows][cols];
    int rowSum[rows], colSum[cols];

    // Read matrix elements
    printf("\nEnter the matrix elements:\n");
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            scanf("%d", &mat[i][j]);
        }
    }

    // Function calls using pointers
    rowWiseSum((int *)mat, rows, cols, rowSum);
    colWiseSum((int *)mat, rows, cols, colSum);

    // Display row-wise sum
    printf("\nRow-wise Sums:\n");
    for (int i = 0; i < rows; i++) {
        printf("Row %d Sum = %d\n", i + 1, rowSum[i]);
    }

    // Display column-wise sum
    printf("\nColumn-wise Sums:\n");
    for (int j = 0; j < cols; j++) {
        printf("Column %d Sum = %d\n", j + 1, colSum[j]);
    }
    return 0;
}
```

