Write a C program using separate functions to perform operations on an array. Implement `readArray()` to input n integers, `reverseArray()` to reverse the array elements, `findMaximum()` to find the maximum value in the reversed array, and `displayResult()` to print both the reversed array and the maximum element. Each function should handle its task independently, and data should be passed appropriately between functions.

**Sol:**
```c
#include <stdio.h>

// Function to read array elements
void readArray(int arr[], int n) {
    printf("Enter %d integers:\n", n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
}

// Function to reverse the array
void reverseArray(int arr[], int n) {
    int start = 0, end = n - 1, temp;
    while (start < end) {
        temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

// Function to find maximum element in the array
int findMaximum(int arr[], int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

// Function to display reversed array and maximum value
void displayResult(int arr[], int n, int max) {
    printf("\nReversed Array:\n");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n\nMaximum Element: %d\n", max);
}

int main() {
    int n;

    // Input array size
    printf("Enter number of elements: ");
    scanf("%d", &n);

    int arr[n];

    // Function calls
    readArray(arr, n);
    reverseArray(arr, n);
    int max = findMaximum(arr, n);
    displayResult(arr, n, max);

    return 0;
}
```

