A shop maintains information about its products, including product_name, quantity, and price. You are required to use an array of structures and pointer arithmetic in C to perform the following task and display the details (product_name, quantity, and price) of products whose quantity is less than 5:

i) Calculate the total stock value of all products (where stock value of each product = quantity × price).

**Sol:**
```c
#include <stdio.h>

// Structure definition
struct Product {
    char name[50];
    int quantity;
    float price;
};

// Function to read product details
void readProducts(struct Product *p, int n) {
    for (int i = 0; i < n; i++) {
        printf("\nEnter details of product %d\n", i + 1);
        printf("Product Name: ");
        scanf("%s", (p + i)->name);
        printf("Quantity: ");
        scanf("%d", &(p + i)->quantity);
        printf("Price: ");
        scanf("%f", &(p + i)->price);
    }
}

// Function to calculate total stock value using pointer arithmetic
float totalStockValue(struct Product *p, int n) {
    float total = 0;
    for (int i = 0; i < n; i++) {
        total += (p + i)->quantity * (p + i)->price;
    }
    return total;
}

// Function to display products with quantity < 5
void displayLowStock(struct Product *p, int n) {
    printf("\nProducts with quantity less than 5:\n");
    printf("-------------------------------------\n");
    for (int i = 0; i < n; i++) {
        if ((p + i)->quantity < 5) {
            printf("Name: %s\n", (p + i)->name);
            printf("Quantity: %d\n", (p + i)->quantity);
            printf("Price: %.2f\n\n", (p + i)->price);
        }
    }
}

int main() {
    int n;

    printf("Enter number of products: ");
    scanf("%d", &n);

    struct Product products[n];

    // Read product details
    readProducts(products, n);

    // Compute total stock value
    float stockValue = totalStockValue(products, n);

    // Display results
    printf("\nTotal Stock Value of All Products: %.2f\n", stockValue);
    displayLowStock(products, n);

    return 0;
}
```

