Develop a C program to merge two text files (`file1.txt` and `file2.txt`) into a third file (`merged.txt`). After merging, the program should display the total number of characters and lines in the merged file. Explain how file pointers and end-of-file (EOF) checks contribute to efficient file concatenation.

**Sol:**
```c
#include <stdio.h>
int main() {
    FILE *f1, *f2, *f3;
    char ch;
    int charCount = 0, lineCount = 0;

    // Open files
    f1 = fopen("file1.txt", "r");
    f2 = fopen("file2.txt", "r");
    f3 = fopen("merged.txt", "w");

    if (f1 == NULL || f2 == NULL || f3 == NULL) {
        printf("Error opening one of the files.\n");
        return 1;
    }

    // Copy file1.txt into merged.txt
    while ((ch = fgetc(f1)) != EOF) {
        fputc(ch, f3);
    }

    // Copy file2.txt into merged.txt
    while ((ch = fgetc(f2)) != EOF) {
        fputc(ch, f3);
    }

    // Close files after writing
    fclose(f1);
    fclose(f2);
    fclose(f3);

    // Reopen merged file for counting
    f3 = fopen("merged.txt", "r");

    // Count characters and lines
    while ((ch = fgetc(f3)) != EOF) {
        charCount++;
        if (ch == '\n') {
            lineCount++;
        }
    }

    fclose(f3);

    // Display results
    printf("Merged successfully into merged.txt\n");
    printf("Total Characters: %d\n", charCount);
    printf("Total Lines: %d\n", lineCount);
    return 0;
}
```

**Scheme:** 2M for Files and merging logic, 1M for Counting Logic, 1 mark for Explanation of EOF checks & File Pointers contribution
